<?php declare(strict_types=1);namespace NpmGateway\Services;final class MarketingFlyerMonthOptions{public const FLOOR='2026-08-01';public function options(\DateTimeImmutable$now):array{$floor=new \DateTimeImmutable(self::FLOOR);$end=$now->modify('first day of this month')->modify('+12 months');if($end<$floor)$end=$floor;$out=[];for($d=$floor;$d<=$end;$d=$d->modify('+1 month'))$out[$d->format('Y-m')]=$d->format('F Y');return$out;}public function normalize(string$value,\DateTimeImmutable$now):string{$options=$this->options($now);if(!isset($options[$value]))throw new \InvalidArgumentException('Select an available flyer month.');return$value.'-01';}public function current(\DateTimeImmutable$now):string{$key=$now->format('Y-m');return isset($this->options($now)[$key])?$key:array_key_first($this->options($now));}}
